          {sources.map(s=><div className="worksheet-card" key={s.id}><label className="worksheet-check"><input type="checkbox" disabled={chosen.months[0].quantityKwh===null} checked={selected.includes(s.id)} onChange={e=>setSelected(v=>e.target.checked?[...v,s.id]:v.filter(id=>id!==s.id))}/>I manually confirm linking {s.originalName} to January</label><p>Printed: {s.printedQuantityKwh} kWh · page 1 · January 1–31</p><button type="button" onClick={()=>void billAction(s)}>Download original bill</button>{selected.includes(s.id)&&s.printedQuantityKwh!==chosen.months[0].quantityKwh&&<label>Explain the printed/entered quantity difference<textarea required maxLength={500} value={reasons[s.id]??""} onChange={e=>setReasons(v=>({...v,[s.id]:e.target.value}))}/><span>The explanation is retained; the discrepancy remains flagged.</span></label>}</div>)}
          {chosen.months[0].quantityKwh===null&&<p>Enter January consumption before linking a January bill. Missing consumption is not zero.</p>}
          <p role="status">{chosen.coverage.knownMonths}/12 months entered · {selected.length?1:0}/12 months with a document · {selected.length===1?1:0}/12 months with exactly one document.</p>
          {selected.length>1&&<p className="worksheet-error">Overlapping January periods: both documents are retained, their quantities are never added, and January has no unambiguous document coverage.</p>}
          {!selected.length&&<p>No bills selected. All twelve months will be shown as missing documents.</p>}
        </>}
